-- Expected result: zero rows. Resolve duplicate metadata keys before trusting joined counts.
SELECT 'CONNECTION' AS source_table, COALESCE(CONNECTION_ID::VARCHAR, '<NULL>') AS join_key, COUNT(*) AS key_rows FROM NAAG_POSTGRES.NAAG_FIVETRAN_LOG.CONNECTION GROUP BY CONNECTION_ID HAVING COUNT(*) > 1 OR CONNECTION_ID IS NULL
UNION ALL
SELECT 'DESTINATION_SCHEMA', COALESCE(CONNECTION_ID::VARCHAR, '<NULL>') || '|' || COALESCE(DESTINATION_ID::VARCHAR, '<NULL>') || '|' || COALESCE(ID::VARCHAR, '<NULL>'), COUNT(*) FROM NAAG_POSTGRES.NAAG_FIVETRAN_LOG.DESTINATION_SCHEMA GROUP BY CONNECTION_ID, DESTINATION_ID, ID HAVING COUNT(*) > 1
UNION ALL
SELECT 'DESTINATION_TABLE', COALESCE(CONNECTION_ID::VARCHAR, '<NULL>') || '|' || COALESCE(DESTINATION_ID::VARCHAR, '<NULL>') || '|' || COALESCE(ID::VARCHAR, '<NULL>'), COUNT(*) FROM NAAG_POSTGRES.NAAG_FIVETRAN_LOG.DESTINATION_TABLE GROUP BY CONNECTION_ID, DESTINATION_ID, ID HAVING COUNT(*) > 1
UNION ALL
SELECT 'DESTINATION_COLUMN', COALESCE(CONNECTION_ID::VARCHAR, '<NULL>') || '|' || COALESCE(DESTINATION_ID::VARCHAR, '<NULL>') || '|' || COALESCE(ID::VARCHAR, '<NULL>'), COUNT(*) FROM NAAG_POSTGRES.NAAG_FIVETRAN_LOG.DESTINATION_COLUMN GROUP BY CONNECTION_ID, DESTINATION_ID, ID HAVING COUNT(*) > 1;
